import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        int total_n = scanner.nextInt();
        int[] firstList = new int[3];
        for (int i = 0; i < 3; i++) {
            firstList[i] = scanner.nextInt();
        }
        int[] secondList = new int[3];
        for (int i = 0; i < 3; i++) {
            secondList[i] = scanner.nextInt();
        }

        int x = firstList[0], y = firstList[1], z = firstList[2];
        int p = secondList[0], q = secondList[1], r = secondList[2];

        int min_value = Math.min(x, p + r) + Math.min(y, q + p) + Math.min(z, r + q);
        int max_value = Math.min(x, q) + Math.min(y, r) + Math.min(z, p);

        System.out.println((total_n - min_value) + " " + max_value);
        scanner.close();
    }
}
